:root {
  --ink: #17202a;
  --muted: #5d6d7e;
  --line: #d5dbdb;
  --paper: #fdfefe;
  --panel: #f4f6f7;
  --accent: #1a5276;
  --farm: #1e8449;
  --thin: #b7950b;
  --skip: #922b21;
  --band: #aed6f1;
  --bandpoint: #1a5276;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  color: var(--ink);
  background: var(--paper);
  font: 14px/1.45 -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}
.skiplink { position: absolute; left: -9999px; }
.skiplink:focus { left: 8px; top: 8px; background: #fff; padding: 4px 8px; z-index: 9; }
main { max-width: 1180px; margin: 0 auto; padding: 20px 18px 48px; }
header.hero { border-bottom: 3px solid var(--accent); padding-bottom: 12px; margin-bottom: 14px; }
header.hero h1 { margin: 0 0 4px; font-size: 26px; letter-spacing: 0.2px; }
header.hero h1 .echo { color: var(--accent); }
header.hero p.lede { margin: 0; color: var(--muted); max-width: 76ch; }
.cards { display: flex; flex-wrap: wrap; gap: 10px; margin: 14px 0; }
.card {
  background: var(--panel); border: 1px solid var(--line); border-radius: 8px;
  padding: 8px 12px; min-width: 150px; flex: 1 1 150px;
}
.card .k { font-size: 11px; text-transform: uppercase; letter-spacing: 0.6px; color: var(--muted); }
.card .v { font-size: 19px; font-weight: 650; }
.card .s { font-size: 12px; color: var(--muted); }
section.proof { background: var(--panel); border: 1px solid var(--line); border-radius: 8px; padding: 10px 14px; margin: 12px 0; }
section.proof h2, section.boardwrap h2, section.livewrap h2 { font-size: 16px; margin: 2px 0 8px; }
section.proof p { margin: 4px 0; }
table { border-collapse: collapse; width: 100%; }
th, td { text-align: left; padding: 5px 7px; border-bottom: 1px solid var(--line); vertical-align: top; }
th { font-size: 11.5px; text-transform: uppercase; letter-spacing: 0.4px; color: var(--muted); white-space: nowrap; }
td.num, th.num { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
tbody tr.row { cursor: pointer; }
tbody tr.row:hover { background: #eaf2f8; }
tbody tr.row:focus { outline: 2px solid var(--accent); outline-offset: -2px; }
.controls { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin: 10px 0; }
.controls input[type="search"] { flex: 1 1 220px; padding: 6px 9px; border: 1px solid var(--line); border-radius: 6px; font: inherit; }
.controls select { padding: 6px; border: 1px solid var(--line); border-radius: 6px; font: inherit; background: #fff; }
.controls label { font-size: 13px; color: var(--muted); display: flex; gap: 5px; align-items: center; }
.chip {
  display: inline-block; padding: 1px 8px; border-radius: 999px; font-size: 11.5px;
  font-weight: 700; letter-spacing: 0.4px; color: #fff; white-space: nowrap;
}
.chip.farm { background: var(--farm); }
.chip.thin { background: var(--thin); }
.chip.skip { background: var(--skip); }
.chip.watch { background: var(--accent); font-weight: 600; }
.bandcell { min-width: 170px; }
.band { position: relative; height: 12px; background: #eef2f3; border-radius: 3px; }
.band .range { position: absolute; top: 2px; height: 8px; background: var(--band); border-radius: 2px; }
.band .point { position: absolute; top: 0; width: 3px; height: 12px; background: var(--bandpoint); border-radius: 1px; }
.bandlbl { font-size: 11px; color: var(--muted); font-variant-numeric: tabular-nums; white-space: nowrap; }
.neg { color: var(--skip); }
.pos { color: var(--farm); }
.drawer {
  border: 2px solid var(--accent); border-radius: 10px; padding: 14px 16px; margin: 14px 0;
  background: #fbfcfc;
}
.drawer h3 { margin: 0 0 2px; font-size: 19px; }
.drawer .sub { color: var(--muted); margin: 0 0 10px; }
.drawer .grid { display: flex; flex-wrap: wrap; gap: 10px; margin: 8px 0; }
.drawer .grid .card { min-width: 120px; }
.drawer ol { margin: 6px 0 2px; padding-left: 20px; }
.drawer ol li { margin: 5px 0; }
.drawer button.close {
  float: right; border: 1px solid var(--line); background: #fff; border-radius: 6px;
  padding: 4px 10px; font: inherit; cursor: pointer;
}
footer { margin-top: 26px; color: var(--muted); font-size: 12.5px; border-top: 1px solid var(--line); padding-top: 10px; }
footer p { margin: 4px 0; max-width: 92ch; }
.empty { padding: 18px; color: var(--muted); text-align: center; }
@media (max-width: 720px) {
  .bandcell { min-width: 110px; }
  main { padding: 14px 10px 36px; }
}
